# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import uncovered_gaps

OPENING = parse_span("09:00-17:00")

class UncoveredGapTests(unittest.TestCase):
    def gaps_for(self, texts):
        worked = [parse_span(text) for text in texts]
        return uncovered_gaps(worked, OPENING)

    def assert_gaps(self, texts, expected):
        self.assertEqual(self.gaps_for(texts), expected)

    def test_nothing_worked_is_one_gap(self):
        self.assert_gaps([], ["gap 09:00-17:00 (480 min)"])

    def test_fully_covered_has_no_gaps(self):
        self.assert_gaps(["09:00-17:00"], [])

    def test_gap_in_the_middle(self):
        worked = ["09:00-12:00", "13:00-17:00"]
        expected = ["gap 12:00-13:00 (60 min)"]
        self.assert_gaps(worked, expected)

    def test_gaps_at_both_ends(self):
        first = "gap 09:00-10:00 (60 min)"
        last = "gap 12:00-17:00 (300 min)"
        self.assert_gaps(["10:00-12:00"], [first, last])

    def test_overlaps_and_touches_merge_first(self):
        worked = [
            "09:00-12:00",
            "11:00-13:00",
            "13:00-14:00"
        ]
        expected = ["gap 14:00-17:00 (180 min)"]
        self.assert_gaps(worked, expected)

    def test_worked_order_does_not_matter(self):
        worked = ["13:00-17:00", "09:00-12:00"]
        expected = ["gap 12:00-13:00 (60 min)"]
        self.assert_gaps(worked, expected)

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError) as caught:
            self.gaps_for(["08:30-10:00"])
        self.assertIn("08:30-10:00", str(caught.exception))

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError) as caught:
            self.gaps_for(["16:00-18:00"])
        self.assertIn("16:00-18:00", str(caught.exception))
